"""Regenerate reference_2x.txt from the 2.x native comment projection.

Run from the repo root: uvx --from ./packages/slopvac-lint python <this file> <this directory>
"""

import json
import sys
from pathlib import Path

from slopvac.pipeline import _comment_projection

root = Path(sys.argv[1])
out = {}
for path in sorted(root.glob("sample.*")):
    if path.suffix == ".json":
        continue
    text = path.read_text(encoding="utf-8")
    projected = _comment_projection(path, text)
    found = []
    for number, line in enumerate(projected.splitlines(), 1):
        column = line.find("ZZZ")
        while column != -1:
            found.append([number, column + 1])
            column = line.find("ZZZ", column + 1)
    out[path.name] = found
lines = [
    "# ZZZ positions the 2.x native comment projection keeps: file line column.",
    "# Generated by running slopvac 2.x _comment_projection on each sample.* file.",
]
for name, found in out.items():
    lines += [f"{name} {a} {b}" for a, b in found]
(root / "reference_2x.txt").write_text("\n".join(lines) + "\n", encoding="utf-8")
